package com.bank.support.service;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Generates all case variants of a reference code; digits stay fixed.
public class CaseVariantService {
    private static final Logger log = Logger.getLogger(CaseVariantService.class.getName());

    public List<String> allCaseVariants(String code) {
        List<char[]> variants = new ArrayList<>();
        variants.add(code.toCharArray());

        for (int i = 0; i < code.length(); i++) {
            if (!Character.isLetter(code.charAt(i))) {
                continue; // digits do not fork the result
            }
            int size = variants.size(); // snapshot before forking this letter
            for (int v = 0; v < size; v++) {
                char[] copy = variants.get(v).clone(); // independent copy
                char c = copy[i];
                copy[i] = Character.isUpperCase(c)
                        ? Character.toLowerCase(c) : Character.toUpperCase(c);
                variants.add(copy);
            }
            int idx = i;
            log.fine(() -> "After letter at index " + idx + " variants = " + variants.size());
        }

        List<String> result = new ArrayList<>();
        for (char[] v : variants) {
            result.add(new String(v));
        }
        log.info(() -> "Generated " + result.size() + " case variants");
        return result;
    }
}
