package com.bank.support;

import com.bank.support.service.CaseVariantService;
import java.util.logging.Logger;

public class CaseVariantApplication {
    private static final Logger log = Logger.getLogger(CaseVariantApplication.class.getName());

    public static void main(String[] args) {
        // Reference code a2b: two letters, one digit.
        CaseVariantService service = new CaseVariantService();
        log.info("NBI reference code variants for 'a2b': "
                + service.allCaseVariants("a2b"));
    }
}
